css:
.cohortsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #20242e;
    background: linear-gradient(160deg, #f4f1ea 0%, #eae4d6 100%);
    border-radius: 18px;
}

.cohortsim-container * {
    box-sizing: border-box;
}

.cohortsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #11203a 0%, #1c3357 55%, #2d4a78 100%);
    color: #f6f2e8;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(17, 32, 58, 0.32);
}

.cohortsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.cohortsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e7c976;
    background: rgba(231, 201, 118, 0.14);
    padding: 5px 14px;
    border-radius: 999px;
}

.cohortsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e6ddca;
}

.cohortsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #3a3320;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.cohortsim-period-counter #currentDay,
.cohortsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #11203a;
}

.cohortsim-round-name {
    background: #11203a;
    color: #e7c976;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.cohortsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a4a16;
    background: #f7e7cf;
    padding: 4px 12px;
    border-radius: 999px;
}

.cohortsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.cohortsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e2d9c6;
    box-shadow: 0 4px 14px rgba(17, 32, 58, 0.07);
    border-top: 4px solid #2d4a78;
}

.cohortsim-card-margin { border-top-color: #1f7a4d; }
.cohortsim-card-fit { border-top-color: #2d4a78; }
.cohortsim-card-renewal { border-top-color: #b8860b; }
.cohortsim-card-deliver { border-top-color: #6a4fb0; }

.cohortsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #7a7058;
}

.cohortsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #11203a;
}

.cohortsim-card-margin .cohortsim-value { color: #1f7a4d; }
.cohortsim-card-fit .cohortsim-value { color: #2d4a78; }
.cohortsim-card-renewal .cohortsim-value { color: #b8860b; }
.cohortsim-card-deliver .cohortsim-value { color: #6a4fb0; }

.cohortsim-sublabel {
    font-size: 0.76rem;
    color: #8a8068;
    line-height: 1.35;
}

.cohortsim-margin-fail .cohortsim-value { color: #c0392b; }
.cohortsim-margin-ok .cohortsim-value { color: #1f7a4d; }

.cohortsim-budget-over { border-top-color: #c0392b; }
.cohortsim-budget-over .cohortsim-value { color: #c0392b; }

.cohortsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #11203a;
    color: #f1ead9;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.cohortsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e7c976;
}

.cohortsim-budget-bar.cohortsim-over #budgetDisplay {
    color: #ff9a86;
}

.cohortsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #b8860b;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(17, 32, 58, 0.05);
}

.cohortsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.cohortsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #11203a;
    margin-bottom: 6px;
}

.cohortsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a3a44;
}

.cohortsim-briefing-text strong { color: #1f7a4d; }
.cohortsim-briefing-text em { color: #8a4a16; font-style: italic; }

.cohortsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e2d9c6;
    box-shadow: 0 4px 14px rgba(17, 32, 58, 0.07);
}

.cohortsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #11203a;
    border-bottom: 2px solid #efe7d6;
    padding-bottom: 8px;
}

.cohortsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #20242e;
    margin: 14px 0 6px;
}

.cohortsim-container select,
.cohortsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d3c8b0;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fbf8f1;
    color: #20242e;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.cohortsim-container select:focus,
.cohortsim-container input[type="number"]:focus {
    outline: none;
    border-color: #b8860b;
    box-shadow: 0 0 0 3px rgba(184, 134, 11, 0.18);
}

.cohortsim-container select option {
    background-color: #ffffff;
    color: #20242e;
}

.cohortsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #b8860b;
}

.cohortsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #1c3357;
    margin-top: 4px;
}

.cohortsim-range-readout span:last-child {
    color: #1f7a4d;
    font-weight: 800;
}

.cohortsim-hint {
    font-size: 0.8rem;
    color: #8a8068;
    margin-top: 4px;
    line-height: 1.4;
}

.cohortsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.cohortsim-container .btn-primary {
    background: linear-gradient(135deg, #11203a 0%, #2d4a78 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #f6f2e8;
    box-shadow: 0 6px 16px rgba(17, 32, 58, 0.28);
}

.cohortsim-container .btn-primary:hover {
    filter: brightness(1.12);
}

.cohortsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d3c8b0;
    color: #7a7058;
}

.cohortsim-coach {
    background: linear-gradient(135deg, #11203a 0%, #1c3357 100%);
    color: #eee6d4;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(17, 32, 58, 0.24);
}

.cohortsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e7c976;
    margin-bottom: 8px;
}

.cohortsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.cohortsim-coach-body strong { color: #ffd98a; }
.cohortsim-coach-body em { color: #ffc1a0; font-style: italic; }

.cohortsim-history,
.cohortsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e2d9c6;
    box-shadow: 0 4px 14px rgba(17, 32, 58, 0.07);
}

.cohortsim-history h3,
.cohortsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #11203a;
}

.cohortsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #20242e;
}

.cohortsim-container table#usfHistoryTable th {
    background: #f1ead9;
    color: #11203a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e2d9c6;
}

.cohortsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0ebdf;
}

.cohortsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf7f0;
}

.cohortsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .cohortsim-container {
        padding: 14px;
    }
    .cohortsim-header h1 {
        font-size: 1.7rem;
    }
    .cohortsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .cohortsim-value {
        font-size: 2rem;
    }
    .cohortsim-clock {
        margin-left: 0;
    }
    .cohortsim-period-counter {
        font-size: 0.88rem;
    }
    .cohortsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .cohortsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ============================================================================
   v1.1.0 — Completion debrief (formatCompletionMessage). Append-only, namespaced
   .cc-cm-* so it cannot collide with the base engine or the view. BEL navy/gold
   palette matched to the header + chart series.
   ============================================================================ */
.cc-cm { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #20242e; text-align: left; max-width: 760px; margin: 0 auto; }
.cc-cm-incomplete { text-align: center; color: #4f5563; font-size: 1rem; padding: 18px; }
.cc-cm-head { display: flex; flex-wrap: wrap; align-items: stretch; gap: 16px; padding: 20px 22px; margin-bottom: 16px;
    background: linear-gradient(135deg, #11203a 0%, #1c3357 58%, #2d4a78 100%); color: #f3efe4; border-radius: 16px;
    border: 1px solid #16294a; box-shadow: 0 10px 28px rgba(17, 32, 58, 0.32); }
.cc-cm-score { text-align: center; padding-right: 20px; border-right: 1px solid rgba(243,239,228,0.22); }
.cc-cm-score-num { font-size: 3.1rem; font-weight: 800; line-height: 1; color: #e7c976; }
.cc-cm-score-den { font-size: 1.1rem; font-weight: 600; color: #cbb98a; margin-left: 2px; }
.cc-cm-score-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; margin-top: 8px; color: #b3bccb; }
.cc-cm-verdict { display: flex; flex-direction: column; justify-content: center; flex: 1 1 auto; min-width: 180px; }
.cc-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; color: #e7c976; font-weight: 700; }
.cc-cm-verdict-tier { font-size: 1.5rem; font-weight: 800; letter-spacing: -0.3px; color: #ffffff; margin-top: 4px; }
.cc-cm-section { margin: 0 0 16px; }
.cc-cm-section-h { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1.1px; font-weight: 700; color: #545a68; margin-bottom: 9px; }
.cc-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.cc-cm-chip { display: inline-flex; align-items: center; gap: 6px; font-size: 0.82rem; font-weight: 600; padding: 6px 12px; border-radius: 999px; border: 1px solid transparent; }
.cc-cm-chip .cc-cm-ico { font-weight: 800; }
.cc-cm-ok { background: #e3f0e8; color: #1f7a4d; border-color: #b4dcc3; }
.cc-cm-no { background: #f7e5e2; color: #a5331f; border-color: #e6bfb6; }
.cc-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 10px; }
.cc-cm-kpi { background: #f7f3e9; border: 1px solid #e2d9c6; border-radius: 12px; padding: 12px 14px; text-align: center; }
.cc-cm-kpi-val { font-size: 1.5rem; font-weight: 800; color: #1c3357; line-height: 1.1; }
.cc-cm-kpi-lbl { font-size: 0.78rem; font-weight: 700; color: #20242e; margin-top: 4px; }
.cc-cm-kpi-sub { font-size: 0.68rem; color: #6a5f47; margin-top: 3px; }
.cc-cm-insights { margin: 0; padding-left: 20px; }
.cc-cm-insights li { font-size: 0.9rem; line-height: 1.5; color: #2a2f3a; margin-bottom: 7px; }
@media (max-width: 520px) { .cc-cm-score { border-right: none; border-bottom: 1px solid rgba(243,239,228,0.22); padding-right: 0; padding-bottom: 14px; } .cc-cm-head { flex-direction: column; } }

