(function() {
    'use strict';

    class CohortAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Custom Cohort`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (USD, in thousands where $k).
            this.BUDGET_CAP = 280;        // $280k client ceiling
            this.COMPETITOR_PRICE = 240;  // off-the-shelf "Healthcare Leadership Academy"
            this.WISHLIST_COST = 410;     // all 11 topics built at standard rates
            this.MARGIN_FLOOR = 25;       // target contribution margin %
            this.SECTOR_MARGIN = 28;      // unit norm
            this.CLASSROOM_CAP = 4;       // client classroom-day cap
            this.WEEKS_CAP = 8;           // delivery window

            // Concept truths.
            this.TRUE_PROBLEM = `transition`;
            this.TRUE_SCOPE = `core`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    fit: 20,
                    renewal: 30,
                    deliver: 25,
                    price: 0,            // $k, set in round 3
                    deliveryCost: 0,     // $k, accumulated
                    margin: null,        // % once priced
                    priced: false,
                    overBudget: false,
                    belowFloor: false,
                    fitHistory: [20],
                    renewalHistory: [30],
                    deliverHistory: [25],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults = a middling/neutral mix, NOT the textbook-correct play.
                state.decisions = {
                    problem: `knowledge`,
                    scope: `half`,
                    questions: 50,
                    format: `classroom`,
                    reuse: `hybrid`,
                    faculty: `substitute`,
                    classroom: 5,
                    posture: `match`,
                    price: 250,
                    lever: `cutprice`,
                    onsite: 50,
                    topicDefense: `apologize`,
                    priceDefense: `prestige`,
                    timeline: `hedge`,
                    renewalCommit: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const pr = document.getElementById(`problemInput`);
                const sc = document.getElementById(`scopeInput`);
                const q = document.getElementById(`questionsInput`);
                if (pr) decisions.problem = pr.value;
                if (sc) decisions.scope = sc.value;
                if (q) decisions.questions = parseInt(q.value, 10);
                if (!Number.isFinite(decisions.questions) || decisions.questions < 0 || decisions.questions > 100) {
                    warn(`warn_questions_range`); return false;
                }
            } else if (round === 2) {
                const fo = document.getElementById(`formatInput`);
                const re = document.getElementById(`reuseInput`);
                const fa = document.getElementById(`facultyInput`);
                const cl = document.getElementById(`classroomInput`);
                if (fo) decisions.format = fo.value;
                if (re) decisions.reuse = re.value;
                if (fa) decisions.faculty = fa.value;
                if (cl) decisions.classroom = parseInt(cl.value, 10);
                if (!Number.isFinite(decisions.classroom) || decisions.classroom < 1 || decisions.classroom > 8) {
                    warn(`warn_classroom_range`); return false;
                }
            } else if (round === 3) {
                const po = document.getElementById(`postureInput`);
                const p = document.getElementById(`priceInput`);
                const le = document.getElementById(`leverInput`);
                const on = document.getElementById(`onsiteInput`);
                if (po) decisions.posture = po.value;
                if (p) decisions.price = parseFloat(p.value);
                if (le) decisions.lever = le.value;
                if (on) decisions.onsite = parseInt(on.value, 10);
                if (!Number.isFinite(decisions.price) || decisions.price < 100 || decisions.price > 400) {
                    warn(`warn_price_range`); return false;
                }
                if (!Number.isFinite(decisions.onsite) || decisions.onsite < 0 || decisions.onsite > 100) {
                    warn(`warn_onsite_range`); return false;
                }
            } else if (round === 4) {
                const td = document.getElementById(`topicDefenseInput`);
                const pd = document.getElementById(`priceDefenseInput`);
                const tl = document.getElementById(`timelineInput`);
                const rc = document.getElementById(`renewalCommitInput`);
                if (td) decisions.topicDefense = td.value;
                if (pd) decisions.priceDefense = pd.value;
                if (tl) decisions.timeline = tl.value;
                if (rc) decisions.renewalCommit = parseInt(rc.value, 10);
                if (!Number.isFinite(decisions.renewalCommit) || decisions.renewalCommit < 0 || decisions.renewalCommit > 100) {
                    warn(`warn_renewal_range`); return false;
                }
            }
            return true;
        }

        // Pure cost model: returns delivery cost in $k from the design decisions so far.
        _computeDeliveryCost(d) {
            // Scope is the dominant driver — building all 11 topics approaches the $410k wish list.
            let cost;
            if (d.scope === `all`) cost = 350;
            else if (d.scope === `half`) cost = 235;
            else cost = 150;             // core 3–4 outcomes

            // Format: all-classroom faculty days are the priciest; virtual is cheap.
            if (d.format === `classroom`) cost += 45;
            else if (d.format === `virtualonly`) cost -= 25;
            else cost += 0;              // blended

            // Build-vs-reuse.
            if (d.reuse === `allcustom`) cost += 55;
            else if (d.reuse === `allreuse`) cost -= 45;
            // hybrid: neutral

            // Faculty mix.
            if (d.faculty === `wait`) cost += 20;        // marquee roster is expensive + idle time
            else if (d.faculty === `substitute`) cost -= 30; // junior associates are cheap
            // mix: neutral (senior + practitioner partner)

            // On-site logistics raise variable cost.
            cost += Math.round((d.onsite || 0) * 0.35);

            // Round 3 value-add / cost levers.
            if (d.lever === `valueadd`) cost += 22;
            else if (d.lever === `cutcost`) cost -= 28;
            else if (d.lever === `cutscope`) cost -= 40;
            // cutprice: no cost change

            return Math.max(120, Math.round(cost));
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let fitDelta = 0, renewalDelta = 0, deliverDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Decode the brief: diagnose the underlying business problem (Common Error 1).
                if (d.problem === this.TRUE_PROBLEM) {
                    fitDelta += 16; renewalDelta += 8; deliverDelta += 4; coachKey = `coach_r1_problem_right`;
                } else if (d.problem === `knowledge`) {
                    fitDelta -= 8; renewalDelta -= 4; coachKey = `coach_r1_knowledge`;
                } else if (d.problem === `prestige`) {
                    fitDelta -= 6; renewalDelta -= 2; coachKey = `coach_r1_prestige`;
                } else {
                    fitDelta -= 6; renewalDelta -= 4; coachKey = `coach_r1_compliance`;
                }

                // Prioritize to a core 3–4 (backward design) vs topic-stuffing all 11.
                if (d.scope === this.TRUE_SCOPE) {
                    fitDelta += 12; renewalDelta += 8;
                    if (d.problem === this.TRUE_PROBLEM) coachKey = `coach_r1_sharp`;
                } else if (d.scope === `all`) {
                    fitDelta -= 12; renewalDelta -= 8; deliverDelta -= 6; coachKey = `coach_r1_stuff`;
                } else {
                    fitDelta -= 4; renewalDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r1_half` : coachKey;
                }

                // Discovery rigor: going back with the right questions before designing.
                if (d.questions >= 60) { fitDelta += 6; renewalDelta += 3; }
                else if (d.questions <= 25) { fitDelta -= 6; coachKey = `coach_r1_noquestions`; }

                summaryKey = (d.problem === this.TRUE_PROBLEM && d.scope === this.TRUE_SCOPE) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Configure under the iron triangle: scope, time, cost (Common Errors 4 & 6).
                // Delivery format vs the 4-day cap and 8-week window.
                switch (d.format) {
                    case `blended`: deliverDelta += 10; fitDelta += 6; renewalDelta += 3; coachKey = `coach_r2_blended`; break;
                    case `classroom`: deliverDelta -= 6; fitDelta += 2; coachKey = `coach_r2_classroom`; break;
                    case `virtualonly`: deliverDelta += 4; fitDelta -= 8; coachKey = `coach_r2_virtual`; break;
                }

                // Classroom-day cap — a clinician off the ward each day. Over 4 = breaks the constraint.
                if (d.classroom <= this.CLASSROOM_CAP) { deliverDelta += 10; }
                else if (d.classroom === 5) { deliverDelta -= 6; if (d.format !== `blended`) coachKey = `coach_r2_overdays`; }
                else { deliverDelta -= 14; renewalDelta -= 4; coachKey = `coach_r2_overdays`; }

                // Build-vs-reuse: custom the few that carry the feel; reuse the rest invisibly.
                switch (d.reuse) {
                    case `hybrid`: fitDelta += 12; renewalDelta += 4; break;
                    case `allcustom`: fitDelta += 6; deliverDelta -= 10; renewalDelta -= 2; coachKey = `coach_r2_allcustom`; break;
                    case `allreuse`: fitDelta -= 14; renewalDelta -= 6; coachKey = `coach_r2_allreuse`; break;
                }

                // Faculty gap: mix senior + practitioner and sequence the marquee; not all-junior.
                switch (d.faculty) {
                    case `mix`: deliverDelta += 12; fitDelta += 4; coachKey = (d.format === `blended` && d.classroom <= this.CLASSROOM_CAP) ? `coach_r2_realistic` : coachKey; break;
                    case `wait`: deliverDelta -= 12; renewalDelta -= 2; coachKey = `coach_r2_wait`; break;
                    case `substitute`: fitDelta -= 10; renewalDelta -= 4; coachKey = `coach_r2_substitute`; break;
                }

                summaryKey = (d.format === `blended` && d.classroom <= this.CLASSROOM_CAP && d.reuse === `hybrid` && d.faculty === `mix`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Price the engagement: distinguish cutting price / cost / scope (Common Errors 2 & 3).
                ds.price = d.price;
                ds.priced = true;
                const cost = this._computeDeliveryCost(d);
                ds.deliveryCost = cost;
                const margin = d.price > 0 ? Math.round(((d.price - cost) / d.price) * 1000) / 10 : 0;
                ds.margin = margin;
                ds.overBudget = d.price > this.BUDGET_CAP;
                ds.belowFloor = margin < this.MARGIN_FLOOR;

                // Over the client ceiling is an instant credibility hit.
                if (ds.overBudget) { renewalDelta -= 12; deliverDelta -= 2; coachKey = `coach_r3_overceiling`; }

                // Margin discipline against the 25% floor.
                if (margin < 0) { renewalDelta -= 18; fitDelta -= 2; coachKey = `coach_r3_lossmaking`; }
                else if (margin < this.MARGIN_FLOOR) { renewalDelta -= 10; coachKey = `coach_r3_belowfloor`; }
                else if (margin >= this.MARGIN_FLOOR && margin <= 45) { renewalDelta += 10; coachKey = `coach_r3_healthy`; }
                else { fitDelta -= 4; renewalDelta -= 4; coachKey = `coach_r3_overpriced`; }

                // Pricing posture: premium needs differentiation; pure match/undercut sacrifices margin.
                switch (d.posture) {
                    case `premium`: fitDelta += 6; renewalDelta += 4; break;
                    case `match`: renewalDelta += 2; coachKey = (coachKey === `coach_default`) ? `coach_r3_match` : coachKey; break;
                    case `phased`: renewalDelta += 6; deliverDelta += 2; coachKey = (coachKey === `coach_default`) ? `coach_r3_phased` : coachKey; break;
                    case `undercut`: renewalDelta -= 4; coachKey = `coach_r3_undercut`; break;
                }

                // The lever: cut COST or add VALUE protect margin; cut SCOPE or PRICE damage it.
                switch (d.lever) {
                    case `cutcost`: renewalDelta += 6; coachKey = (coachKey === `coach_default`) ? `coach_r3_cutcost` : coachKey; break;
                    case `valueadd`: fitDelta += 10; renewalDelta += 6; coachKey = (margin >= this.MARGIN_FLOOR) ? `coach_r3_valueadd` : coachKey; break;
                    case `cutscope`: fitDelta -= 12; renewalDelta -= 6; coachKey = `coach_r3_cutscope`; break;
                    case `cutprice`: renewalDelta -= 2; break;
                }

                // On-site at the hospital raises fit for shift workers (cost already counted).
                if (d.onsite >= 60) { fitDelta += 6; }
                else if (d.onsite <= 20) { fitDelta -= 4; }

                summaryKey = (!ds.overBudget && margin >= this.MARGIN_FLOOR && (d.lever === `cutcost` || d.lever === `valueadd`)) ? `sum_r3_good`
                    : (margin < this.MARGIN_FLOOR ? `sum_r3_loss` : `sum_r3_weak`);
            } else if (round === 4) {
                // Defend & commit (Common Errors 1, 3, 4, 5).
                // Topic-drop defense: tie to the business outcome, don't apologize or blame budget.
                switch (d.topicDefense) {
                    case `outcome`: fitDelta += 8; renewalDelta += 8; coachKey = `coach_r4_outcome`; break;
                    case `apologize`: fitDelta -= 6; renewalDelta -= 6; coachKey = `coach_r4_apologize`; break;
                    case `blame`: renewalDelta -= 8; coachKey = `coach_r4_blame`; break;
                }

                // Price objection: name the differentiation, don't reflexively discount or wave the brand.
                switch (d.priceDefense) {
                    case `differentiate`: renewalDelta += 10; fitDelta += 4; coachKey = (d.topicDefense === `outcome`) ? `coach_r4_differentiate` : coachKey; break;
                    case `discount`: renewalDelta -= 6; coachKey = `coach_r4_discount`;
                        // A reflexive discount also re-opens the margin wound.
                        if (ds.priced) { ds.price = Math.max(120, ds.price - 40); ds.margin = Math.round(((ds.price - ds.deliveryCost) / ds.price) * 1000) / 10; ds.belowFloor = ds.margin < this.MARGIN_FLOOR; }
                        break;
                    case `prestige`: renewalDelta -= 4; coachKey = `coach_r4_prestige`; break;
                }

                // Timeline realism: committed milestones reconciled with lead-times vs over-promising.
                switch (d.timeline) {
                    case `milestones`: deliverDelta += 12; renewalDelta += 4; break;
                    case `promise`: deliverDelta -= 8; renewalDelta -= 4; coachKey = `coach_r4_promise`; break;
                    case `hedge`: deliverDelta -= 4; renewalDelta -= 4; coachKey = `coach_r4_hedge`; break;
                }

                // The audition logic: holding a genuine margin above the floor (not gouging, not gutting).
                if (ds.margin !== null) {
                    if (ds.margin >= this.MARGIN_FLOOR && ds.margin <= 45 && d.renewalCommit >= 40 && d.renewalCommit <= 80) {
                        renewalDelta += 8; if (coachKey === `coach_default`) coachKey = `coach_r4_audition`;
                    } else if (ds.margin > 45 && d.renewalCommit < 30) {
                        renewalDelta -= 6; coachKey = `coach_r4_oneoff`;
                    } else if (ds.margin < this.MARGIN_FLOOR) {
                        renewalDelta -= 4;
                    }
                }

                summaryKey = (d.topicDefense === `outcome` && d.priceDefense === `differentiate` && d.timeline === `milestones`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply deltas to the 0–100 KPIs.
            ds.fit = Math.max(0, Math.min(100, ds.fit + fitDelta));
            ds.deliver = Math.max(0, Math.min(100, ds.deliver + deliverDelta));

            // Renewal probability is also dragged by an over-budget price, a sub-floor margin,
            // and weak deliverability — the audition fails on any of the three tensions.
            let renewalDrag = 0;
            if (ds.overBudget) renewalDrag += 3;
            if (ds.belowFloor && ds.priced) renewalDrag += 4;
            if (ds.deliver < 35) renewalDrag += 3;
            ds.renewal = Math.max(0, Math.min(100, ds.renewal + renewalDelta - renewalDrag));

            ds.fitHistory.push(Math.round(ds.fit));
            ds.renewalHistory.push(Math.round(ds.renewal));
            ds.deliverHistory.push(Math.round(ds.deliver));

            // v1.1.0 fix — persist composite where Express grading/reporting reads it
            // (results_utils.php express_resolveDomainScore -> performance.overallScore, then top-level score).
            const composite = this._composite(ds);
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = composite;
            ds.score = composite;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                score: composite,
                overallScore: composite,
                fit: Math.round(ds.fit),
                fitDelta: Math.round(fitDelta),
                renewal: Math.round(ds.renewal),
                renewalDelta: Math.round(renewalDelta - renewalDrag),
                deliver: Math.round(ds.deliver),
                deliverDelta: Math.round(deliverDelta),
                price: ds.price,
                deliveryCost: ds.deliveryCost,
                margin: ds.margin,
                overBudget: ds.overBudget,
                belowFloor: ds.belowFloor,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

