        _composite(ds) {
            // Verbatim v1.0.0 composite (was inline in getPerformanceSummary), extracted so the
            // per-period persisted score and the completion summary are identical by construction.
            const fit = Math.round(ds.fit);
            const renewal = Math.round(ds.renewal);
            const deliver = Math.round(ds.deliver);
            return Math.round(fit * 0.30 + renewal * 0.40 + deliver * 0.30);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const fit = Math.round(ds.fit);
            const renewal = Math.round(ds.renewal);
            const deliver = Math.round(ds.deliver);
            const margin = ds.margin === null ? 0 : ds.margin;

            const profitable = margin >= this.MARGIN_FLOOR && !ds.overBudget;
            const wonRenewal = renewal >= 60;
            const deliverable = deliver >= 55;
            const composite = this._composite(ds);

            // v1.1.0 fix — tier labels were hardcoded English; now i18n-keyed (localized es).
            let tierKey = `grade_lost`;
            if (profitable && wonRenewal && deliverable && composite >= 70) tierKey = `grade_won`;
            else if (profitable && wonRenewal) tierKey = `grade_credible`;
            else if (wonRenewal && !profitable) tierKey = `grade_lostmoney`;
            else if (profitable && !wonRenewal) tierKey = `grade_generic`;
            else if (composite >= 45) tierKey = `grade_improving`;
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            if (profitable && wonRenewal && deliverable) insights.push(window.mySimulation.t(`insight_won`));
            else if (!profitable && ds.priced) insights.push(window.mySimulation.t(`insight_lossmaking`));
            else if (!wonRenewal) insights.push(window.mySimulation.t(`insight_generic`));

            if (ds.overBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            if (ds.belowFloor && ds.priced) insights.push(window.mySimulation.t(`insight_belowfloor`));
            if (deliver < 45) insights.push(window.mySimulation.t(`insight_undeliverable`));
            if (fit < 45) insights.push(window.mySimulation.t(`insight_lowfit`));
            if (profitable && wonRenewal && deliverable && fit >= 65) insights.push(window.mySimulation.t(`insight_audition`));

            return {
                fit: fit,
                renewal: renewal,
                deliver: deliver,
                margin: margin,
                price: ds.price,
                profitable: profitable,
                composite: composite,
                performance: performance,
                performanceKey: tierKey,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
